mapper.update:
update account_refresh
set token_value = #{tokenValue}
where 	account_id = #{accountId}	
		and 
		user_agent = #{userAgent}
		and
		user_address = #{userAddress}

mapper.select:
select * from account_refresh
where 	account_id = #{accountId}	
		and 
		user_agent = #{userAgent}
		and
		user_address = #{userAddress}

mapper.delete:
delete account_refresh
where 	account_id = #{accountId}	
		and 
		user_agent = #{userAgent}
		and
		user_address = #{userAddress}
